in vec3 normal,fragPos;in vec2 texCoord;layout(location=0)out vec4 FragColor;layout(location=1)out vec4 BrightColor;uniform vec4 ballColor,lightColor,lightPosition,ambientColor;uniform float shininess;uniform int isEmissive,lightType;uniform vec4 secondLightColor,secondLightPosition;uniform int useSecondLight,secondLightType;uniform vec4 thirdLightColor,thirdLightPosition;uniform int useThirdLight,thirdLightType,numLights,utiliseWater;uniform float time,waveStrength,waveSpeed;uniform int isWater;vec3 applyWaves(vec3 position,vec3 normal){if(isWater!=1)return position;float amplitude=waveStrength*.05;normal=position;normal.y+=sin(5.*position.x+time*waveSpeed)*cos(5.*position.z+time*waveSpeed*.7)*amplitude+sin(6.5*position.z+time*waveSpeed*.8)*cos(8.5*position.x+time*waveSpeed*1.1)*amplitude*.8;return normal;}void main(){vec3 norm=normalize(normal),lightDir;float attenuation=1.;if(lightType==1){lightDir=normalize(vec3(lightPosition)-fragPos);float distance=length(vec3(lightPosition)-fragPos);attenuation=1./(1.+.09*distance+.032*distance*distance);}else lightDir=normalize(-vec3(lightPosition));vec3 ambient=vec3(ambientColor);float diff=max(dot(norm,lightDir),0.);vec3 diffuse=diff*vec3(lightColor),viewDir=normalize(vec3(0,0,5)-fragPos);lightDir=normalize(lightDir+viewDir);diff=pow(max(dot(norm,lightDir),0.),shininess*2.);vec3 specular=diff*vec3(lightColor);diffuse*=attenuation;specular*=attenuation;diff=pow(1.-max(dot(viewDir,norm),0.),3.);vec3 rimLight=diff*vec3(lightColor)*.3*attenuation,secondaryLightContribution=vec3(0);if(useSecondLight==1){vec3 secondLightDir;float secondAttenuation=1.;if(secondLightType==1){secondLightDir=normalize(vec3(secondLightPosition)-fragPos);float secondDistance=length(vec3(secondLightPosition)-fragPos);secondAttenuation=1./(1.+.09*secondDistance+.032*secondDistance*secondDistance);}else secondLightDir=normalize(-vec3(secondLightPosition));float secondDiff=max(dot(norm,secondLightDir),0.);vec3 secondDiffuse=secondDiff*vec3(secondLightColor);secondLightDir=normalize(secondLightDir+viewDir);secondDiff=pow(max(dot(norm,secondLightDir),0.),shininess*2.);secondLightDir=secondDiff*vec3(secondLightColor);secondDiffuse*=secondAttenuation;secondLightDir*=secondAttenuation;secondaryLightContribution=secondDiffuse+secondLightDir;}vec3 thirdLightContribution=vec3(0);if(useThirdLight==1){vec3 thirdLightDir;float thirdAttenuation=1.;if(thirdLightType==1){thirdLightDir=normalize(vec3(thirdLightPosition)-fragPos);float thirdDistance=length(vec3(thirdLightPosition)-fragPos);thirdAttenuation=1./(1.+.09*thirdDistance+.032*thirdDistance*thirdDistance);}else thirdLightDir=normalize(-vec3(thirdLightPosition));float thirdDiff=max(dot(norm,thirdLightDir),0.);vec3 thirdDiffuse=thirdDiff*vec3(thirdLightColor);thirdLightDir=normalize(thirdLightDir+viewDir);thirdDiff=pow(max(dot(norm,thirdLightDir),0.),shininess*2.);thirdLightDir=thirdDiff*vec3(thirdLightColor);thirdDiffuse*=thirdAttenuation;thirdLightDir*=thirdAttenuation;thirdLightContribution=thirdDiffuse+thirdLightDir;}if(isEmissive==1)FragColor=vec4(vec3(ballColor)*1.5,ballColor.w);else if(utiliseWater==1){vec3 wavyPos=applyWaves(fragPos,norm);norm=normalize(normalize(cross(applyWaves(wavyPos+vec3(.01,0,0),vec3(0,1,0))-applyWaves(wavyPos-vec3(.01,0,0),vec3(0,1,0)),applyWaves(wavyPos+vec3(0,0,.01),vec3(0,1,0))-applyWaves(wavyPos-vec3(0,0,.01),vec3(0,1,0)))));float waterRipple=sin(length(texCoord*10.)-time*2.)*.05,wavyDiff=max(dot(norm,normalize(vec3(lightPosition)-wavyPos)),0.);diffuse=wavyDiff*vec3(lightColor);wavyDiff=pow(max(dot(norm,lightDir),0.),shininess*(2.+sin(time)));specular=(1.+waterRipple*2.)*wavyDiff*vec3(lightColor);wavyPos=mix(vec3(0,.827,.98),vec3(1),pow(1.-max(dot(viewDir,norm),0.),3.));diffuse*=attenuation;specular*=attenuation;rimLight=diff*vec3(lightColor)*(.3+sin(time*1.3)*.1)*attenuation;wavyPos=mix((ambient+diffuse*(sin(time*.5)*.1+.9)+specular+rimLight)*mix(vec3(0,.5,1),vec3(0,.7,.8),sin(time*.3)*.5+.5),wavyPos,(.5+waterRipple*4.+sin(time*.8)*.1)*di